// RegisterEmployee.jsx — Admin form to register a new employee account (HR Dashboard tab, also /register-employee).
// Left: the form (auto-generated Employee ID, name, email). Right: a live preview of the new account and what happens
// next. After registering, the login details stay on screen (with copy buttons) until the admin is done —
// the default password is generated by the backend (<EmployeeID>@<year>) and shown here once.
import { useState, useEffect } from "react";
import { useToast } from "../context/ToastContext";
import axios from "../services/axios";
import { useNavigate } from "react-router-dom";
import {
  Loader2, Copy, Check, UserPlus, User, Mail, Hash, RefreshCw, AlertCircle, KeyRound,
  Send, ShieldCheck, ArrowLeft,
} from "lucide-react";
import PersonAvatar from "../components/PersonAvatar";

// Axios gives no response when the server can't be reached at all
const serverDown = (err) => !err?.response;
const SERVER_DOWN = "Can't reach the server — make sure the backend is running.";

const inputCls =
  "h-11 w-full rounded-xl border border-gray-200 bg-gray-50/70 pl-10 pr-3 text-sm text-gray-800 outline-none transition " +
  "placeholder:text-gray-400 focus:border-indigo-300 focus:bg-white focus:ring-4 focus:ring-indigo-50";

function Label({ htmlFor, children, hint }) {
  return (
    <div className="mb-1.5 flex items-baseline justify-between gap-2">
      <label htmlFor={htmlFor} className="text-[11px] font-bold uppercase tracking-widest text-gray-400">{children}</label>
      {hint && <span className="text-[11px] text-gray-400">{hint}</span>}
    </div>
  );
}

const NEXT_STEPS = [
  { Icon: KeyRound,    title: "A temporary password is created", text: "You'll see it once, right after registering." },
  { Icon: Send,        title: "Share the login details",          text: "Copy them and send them to the employee." },
  { Icon: ShieldCheck, title: "They sign in and change it",       text: "Then they complete their own profile." },
];

const RegisterEmployee = ({ setActiveTab }) => {
  const toast    = useToast();
  const navigate = useNavigate();
  const inTab    = typeof setActiveTab === "function"; // inside the HR Dashboard (vs. the standalone page)

  const [form, setForm]             = useState({ name: "", email: "" });
  const [nextId, setNextId]         = useState("");
  const [idLoading, setIdLoading]   = useState(true);
  const [idError, setIdError]       = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [formError, setFormError]   = useState("");
  const [created, setCreated]       = useState(null); // { name, email, employeeId, password } after success
  const [copied, setCopied]         = useState(null); // which field was just copied

  // Fetch next auto-generated employee ID (the cancel flag stops React dev mode's double-run from toasting twice)
  const loadNextId = (isCancelled = () => false) => {
    setIdLoading(true);
    setIdError(null);
    axios.get("/users/next-employee-id")
      .then(r => { if (!isCancelled()) setNextId(r.data.nextId); })
      .catch(err => {
        if (isCancelled()) return;
        const msg = serverDown(err) ? SERVER_DOWN : "Could not load the next Employee ID.";
        setIdError(msg);
        toast.error(msg);
      })
      .finally(() => { if (!isCancelled()) setIdLoading(false); });
  };

  useEffect(() => {
    let cancelled = false;
    loadNextId(() => cancelled);
    return () => { cancelled = true; };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
    if (formError) setFormError("");
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!nextId) return setFormError("The Employee ID isn't ready yet — try again in a moment.");
    setSubmitting(true);
    setFormError("");
    try {
      const { data } = await axios.post("/auth/register", {
        employeeId: nextId,
        name:       form.name.trim(),
        email:      form.email.trim(),
        role:       "employee",
      });
      setCreated({ name: data.name, email: data.email, employeeId: data.employeeId, password: data.defaultPassword });
      toast.success(`${data.name} registered.`);
    } catch (err) {
      setFormError(serverDown(err) ? SERVER_DOWN : (err?.response?.data?.message || err.message));
    } finally {
      setSubmitting(false);
    }
  };

  const copy = async (key, text) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(key);
      setTimeout(() => setCopied(c => (c === key ? null : c)), 1800);
    } catch {
      toast.error("Couldn't copy — select the text and copy it manually.");
    }
  };

  const registerAnother = () => {
    setCreated(null);
    setForm({ name: "", email: "" });
    setFormError("");
    loadNextId();
  };

  const handleDone = () => {
    if (inTab) setActiveTab("employees");
    else navigate("/hr");
  };

  const wrap = (children) =>
    inTab ? children : <div className="min-h-screen bg-gray-50 p-6">{children}</div>;

  /* ── Success: login details stay until the admin is done ── */
  if (created) {
    const rows = [
      ["Employee ID", created.employeeId],
      ["Email", created.email],
      ["Password", created.password],
    ];
    const allText = `InsightDesk login\nName: ${created.name}\nEmployee ID: ${created.employeeId}\nEmail: ${created.email}\nPassword: ${created.password}`;
    return wrap(
      <div className="mx-auto w-full max-w-lg overflow-hidden rounded-2xl border border-gray-100 bg-white shadow-sm">
        <div className="h-1 bg-gradient-to-r from-indigo-500 via-violet-500 to-blue-500" />
        <div className="p-7">
          <div className="flex items-center gap-3">
            <div className="relative">
              <PersonAvatar person={{ name: created.name }} size={48} />
              <span className="absolute -bottom-1 -right-1 flex h-5 w-5 items-center justify-center rounded-full bg-emerald-500 ring-2 ring-white">
                <Check className="h-3 w-3 text-white" />
              </span>
            </div>
            <div className="min-w-0">
              <h2 className="text-lg font-bold text-gray-900">Employee registered</h2>
              <p className="truncate text-sm text-gray-500">{created.name} can sign in now.</p>
            </div>
          </div>

          <p className="mb-2 mt-6 text-[10px] font-bold uppercase tracking-widest text-gray-400">Login details to share</p>
          <ul className="space-y-2">
            {rows.map(([label, value]) => (
              <li key={label} className="flex items-center gap-3 rounded-xl border border-gray-100 bg-gray-50 px-3.5 py-2.5">
                <div className="min-w-0 flex-1">
                  <p className="text-[10px] font-bold uppercase tracking-widest text-gray-400">{label}</p>
                  <p className={`mt-0.5 select-all truncate text-sm font-semibold text-gray-800 ${label !== "Email" ? "font-mono tracking-wide" : ""}`}>{value}</p>
                </div>
                <button type="button" onClick={() => copy(label, value)}
                  className="flex flex-shrink-0 cursor-pointer items-center gap-1 rounded-full border border-gray-200 bg-white px-2.5 py-1 text-[11px] font-semibold text-gray-500 transition hover:bg-gray-100"
                  aria-label={`Copy ${label}`}>
                  {copied === label ? <><Check className="h-3 w-3 text-emerald-500" /> Copied</> : <><Copy className="h-3 w-3" /> Copy</>}
                </button>
              </li>
            ))}
          </ul>

          <button type="button" onClick={() => copy("all", allText)}
            className="mt-3 inline-flex w-full cursor-pointer items-center justify-center gap-2 rounded-full border border-indigo-200 px-4 py-2 text-sm font-semibold text-indigo-600 transition hover:bg-indigo-50">
            {copied === "all" ? <><Check className="h-4 w-4" /> All details copied</> : <><Copy className="h-4 w-4" /> Copy all details</>}
          </button>

          <p className="mt-4 flex items-start gap-2 rounded-xl border border-amber-100 bg-amber-50 px-3.5 py-2.5 text-xs leading-relaxed text-amber-700">
            <KeyRound className="mt-0.5 h-3.5 w-3.5 flex-shrink-0" />
            This password is shown only now. Share it with the employee and ask them to change it after their first sign-in.
          </p>

          <div className="mt-5 flex gap-3">
            <button type="button" onClick={registerAnother}
              className="inline-flex flex-1 cursor-pointer items-center justify-center gap-1.5 rounded-full border border-gray-200 px-4 py-2 text-sm font-semibold text-gray-600 transition hover:bg-gray-50">
              <UserPlus className="h-4 w-4" /> Register another
            </button>
            <button type="button" onClick={handleDone}
              className="flex-1 cursor-pointer rounded-full bg-gray-800 px-4 py-2 text-sm font-semibold text-white transition hover:bg-gray-900">
              Done
            </button>
          </div>
        </div>
      </div>
    );
  }

  /* ── The form ── */
  const previewName = form.name.trim() || "New employee";
  return wrap(
    <div className="space-y-5">
      {/* Section header */}
      <div className="flex items-end justify-between gap-4">
        <div>
          <h2 className="text-lg font-bold text-gray-900">Register an employee</h2>
          <p className="mt-0.5 text-sm text-gray-500">Create their account — the Employee ID and a temporary password are generated for you.</p>
        </div>
        {!inTab && (
          <button type="button" onClick={handleDone}
            className="inline-flex cursor-pointer items-center gap-1.5 rounded-full border border-gray-200 bg-white px-3 py-1.5 text-xs font-semibold text-gray-600 shadow-sm transition hover:bg-gray-50">
            <ArrowLeft className="h-3.5 w-3.5" /> Back to HR Dashboard
          </button>
        )}
      </div>

      <div className="grid items-start gap-5 lg:grid-cols-[minmax(0,1.25fr)_minmax(0,1fr)]">
        {/* Form */}
        <form onSubmit={handleSubmit} className="space-y-5 rounded-2xl border border-gray-100 bg-white p-6 shadow-sm">
          {/* Employee ID — auto-generated */}
          <div>
            <Label htmlFor="reg-id" hint="Generated automatically">Employee ID</Label>
            <div className="relative">
              <Hash className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
              <input id="reg-id" type="text" readOnly tabIndex={-1}
                value={idLoading ? "Generating…" : (nextId || "—")}
                className="h-11 w-full cursor-default rounded-xl border border-dashed border-indigo-200 bg-indigo-50/50 pl-10 pr-24 font-mono text-sm font-semibold tracking-widest text-indigo-700 outline-none" />
              <span className="absolute right-2 top-1/2 -translate-y-1/2">
                {idLoading ? (
                  <Loader2 className="mr-1.5 h-4 w-4 animate-spin text-indigo-400" />
                ) : idError ? (
                  <button type="button" onClick={() => loadNextId()}
                    className="inline-flex cursor-pointer items-center gap-1 rounded-full bg-white px-2.5 py-1 text-[11px] font-semibold text-indigo-600 shadow-sm hover:bg-indigo-50">
                    <RefreshCw className="h-3 w-3" /> Retry
                  </button>
                ) : (
                  <span className="rounded-full bg-white px-2 py-0.5 text-[10px] font-bold uppercase tracking-widest text-indigo-500 shadow-sm">Auto</span>
                )}
              </span>
            </div>
            {idError && <p className="mt-1.5 text-xs text-red-500">{idError}</p>}
          </div>

          {/* Name */}
          <div>
            <Label htmlFor="reg-name">Full name</Label>
            <div className="relative">
              <User className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
              <input id="reg-name" name="name" type="text" required autoFocus autoComplete="off"
                placeholder="e.g. Priya Sharma" value={form.name} onChange={handleChange} className={inputCls} />
            </div>
          </div>

          {/* Email */}
          <div>
            <Label htmlFor="reg-email" hint="They'll sign in with this">Work email</Label>
            <div className="relative">
              <Mail className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
              <input id="reg-email" name="email" type="email" required autoComplete="off"
                placeholder="name@company.com" value={form.email} onChange={handleChange} className={inputCls} />
            </div>
          </div>

          {formError && (
            <div role="alert" className="flex items-start gap-2 rounded-xl border border-red-100 bg-red-50 px-3.5 py-2.5 text-sm text-red-600">
              <AlertCircle className="mt-0.5 h-4 w-4 flex-shrink-0" /> <span>{formError}</span>
            </div>
          )}

          <button type="submit" disabled={submitting || idLoading || !nextId}
            className="inline-flex h-11 w-full cursor-pointer items-center justify-center gap-2 rounded-full bg-gray-800 text-sm font-semibold text-white shadow-sm transition hover:bg-gray-900 disabled:cursor-not-allowed disabled:opacity-50">
            {submitting ? <Loader2 className="h-4 w-4 animate-spin" /> : <UserPlus className="h-4 w-4" />}
            {submitting ? "Registering…" : "Register employee"}
          </button>
        </form>

        {/* Preview + what happens next */}
        <aside className="space-y-4">
          <div className="overflow-hidden rounded-2xl border border-gray-100 bg-white shadow-sm">
            <div className="h-1 bg-gradient-to-r from-indigo-500 via-violet-500 to-blue-500" />
            <div className="p-5">
              <p className="text-[10px] font-bold uppercase tracking-widest text-gray-400">Preview</p>
              <div className="mt-3 flex items-center gap-3">
                <PersonAvatar person={{ name: previewName }} size={48} />
                <div className="min-w-0">
                  <p className={`truncate text-base font-bold ${form.name.trim() ? "text-gray-900" : "text-gray-300"}`}>{previewName}</p>
                  <p className="truncate text-xs text-gray-500">{form.email.trim() || "email not set"}</p>
                </div>
              </div>
              <div className="mt-4 flex flex-wrap gap-2">
                <span className="rounded-full bg-indigo-50 px-2.5 py-1 font-mono text-xs font-semibold tracking-wide text-indigo-700">{nextId || "IDE…"}</span>
                <span className="rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-semibold text-emerald-700">Employee</span>
              </div>
            </div>
          </div>

          <div className="rounded-2xl border border-gray-100 bg-white p-5 shadow-sm">
            <p className="text-[10px] font-bold uppercase tracking-widest text-gray-400">What happens next</p>
            <ol className="mt-3 space-y-3.5">
              {NEXT_STEPS.map(({ Icon, title, text }, i) => (
                <li key={title} className="flex gap-3">
                  <span className="relative flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-xl bg-gray-50">
                    {Icon && <Icon className="h-4 w-4 text-indigo-500" />}
                    <span className="absolute -right-1 -top-1 flex h-4 w-4 items-center justify-center rounded-full bg-gray-800 text-[9px] font-bold text-white">{i + 1}</span>
                  </span>
                  <span className="min-w-0">
                    <span className="block text-sm font-semibold text-gray-800">{title}</span>
                    <span className="block text-xs text-gray-500">{text}</span>
                  </span>
                </li>
              ))}
            </ol>
          </div>
        </aside>
      </div>
    </div>
  );
};

export default RegisterEmployee;
